<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\SubscriptionEligibilityService;Auth::requirePermission('ELIGIBILITY_VIEW_OWN');$rows=SubscriptionEligibilityService::ownEligibility();$pageTitle='Fleet Eligibility';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Fleet eligibility</h1><p>Latest automatic assessment for each registered truck.</p></div><span class="badge"><?=h(count(array_filter($rows,fn($r)=>$r['assessment_result']==='eligible')))?> available</span></div><div class="notice">Eligibility is recalculated after subscription activation and Driver–truck linking, and by the scheduled CLI task. Availability cannot be manually overridden.</div><div class="card table-wrap" tabindex="0" aria-label="Scrollable fleet eligibility table"><table style="min-width:1120px"><thead><tr><th>Truck</th><th>Driver</th><th>Result</th><th>Availability</th><th>Reasons</th><th>Assessed UTC</th></tr></thead><tbody><?php foreach($rows as$r):$reasons=json_decode((string)$r['reason_codes_json'],true)?:[];?><tr><td><?=h($r['registration_number'].' · '.$r['make_name'].' '.$r['model_name'])?></td><td><?=h($r['driver_name']?:'Not linked')?></td><td><span class="status-pill"><?=h($r['assessment_result'])?></span></td><td><?=h($r['availability_status'])?></td><td><?=h($reasons?implode(', ',$reasons):'All checks passed')?></td><td><?=h($r['assessed_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="muted">No eligibility assessments yet. An active subscription and registered trucks are required.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
